/* test_int.c: arbitrary-precision Int (spec/cabi.md 2.5): addition, subtraction, multiplication, negation, the one
   division cplrt_int_divrem (quotient toward zero, remainder a - q * b, semantics S37), ordering, the decimal reader of
   stdlib.md S25 and the canonical decimal writer, and the conversions with machine integers and 64-bit word arrays.
   Every expected result was computed with exact integer arithmetic (Python), including divisions that take algorithm
   D's add-back step. */
#define _GNU_SOURCE 1
#define CPLRT_NS rttest
#define CPLRT(name) cplrt_rttest__##name
#define CPLPKG(name) cplpkg_rttest__##name
#include "cpl_rt_internal.h"
#include "cpl_rt_gen.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void rttest_runtime_init(cplrt_runtime *rt, uint64_t max_heap_bytes);
uint64_t rttest_runtime_fini(cplrt_runtime *rt);

static int failures, checks;
#define CHECK(c)                                                                                                       \
    do {                                                                                                               \
        checks++;                                                                                                      \
        if (!(c)) {                                                                                                    \
            failures++;                                                                                                \
            printf("%s:%d: CHECK(%s) failed\n", __FILE__, __LINE__, #c);                                               \
        }                                                                                                              \
    } while (0)

static cplrt_runtime rt;
static cplrt_cx cx;
static cplrt_memory_record memory;

/* An Int from its decimal text (the reader of S25 accepts every canonical decimal). */
static cplrt_w parse(const char *s)
{
    cplrt_w w = 0;
    int st = CPLRT(int_parse)(&rt, s, strlen(s), &w);
    CHECK(st == CPLRT_OK);
    return w;
}

/* The value is its canonical decimal, and lies in the small range exactly when it is an immediate (2.5). */
static void expect(cplrt_w w, const char *want, int line)
{
    cplrt_sbuf b;
    cplrt_sbuf_init(&b, &rt);
    CPLRT(int_write)(&b, w);
    checks++;
    if (b.status != CPLRT_OK || strcmp(b.ptr, want) != 0) {
        failures++;
        printf("test_int.c:%d: got %s, want %s\n", line, b.status == CPLRT_OK ? b.ptr : "(no memory)", want);
    }
    int64_t v = 0;
    int fits = CPLRT(int_to_i64)(w, &v) && v >= CPLRT_SMALL_MIN && v <= CPLRT_SMALL_MAX;
    checks++;
    if (fits != cplrt_is_small(w)) {
        failures++;
        printf("test_int.c:%d: %s is %s, but it %s the small range\n", line, want,
               cplrt_is_small(w) ? "small" : "a bigint", fits ? "lies in" : "lies outside");
    }
    CPLRT(sbuf_free)(&b);
}
#define EXPECT(w, want) expect((w), (want), __LINE__)

