static void test_vectors(void)
{
    for (size_t i = 0; i < sizeof vectors / sizeof vectors[0]; i++) {
        const vector *v = &vectors[i];
        cplrt_w a = parse(v->a), b = parse(v->b), r = 0, q = 0;
        EXPECT(a, v->a);
        EXPECT(b, v->b);
        CHECK(cplrt_int_add(&cx, 0, a, b, &r) == CPLRT_OK);
        EXPECT(r, v->sum);
        CHECK(cplrt_int_sub(&cx, 0, a, b, &r) == CPLRT_OK);
        EXPECT(r, v->difference);
        CHECK(cplrt_int_mul(&cx, 0, a, b, &r) == CPLRT_OK);
        EXPECT(r, v->product);
        CHECK(cplrt_int_cmp(a, b) == v->order);
        CHECK(cplrt_int_cmp(b, a) == -v->order);
        if (v->quotient[0] != '\0') {
            CHECK(cplrt_int_divrem(&cx, 0, a, b, &q, &r) == CPLRT_OK);
            EXPECT(q, v->quotient);
            EXPECT(r, v->remainder);
            cplrt_w q2 = 0, r2 = 0;
            CHECK(cplrt_int_div(&cx, 0, a, b, &q2) == CPLRT_OK && cplrt_int_cmp(q2, q) == 0);
            CHECK(cplrt_int_rem(&cx, 0, a, b, &r2) == CPLRT_OK && cplrt_int_cmp(r2, r) == 0);
            cplrt_release(q2);
            cplrt_release(r2);
        } else {
            cplrt_w keep_q = cplrt_small(11), keep_r = cplrt_small(12);
            CHECK(cplrt_int_divrem(&cx, 3, a, b, &keep_q, &keep_r) == CPLRT_FAULT);
            CHECK(keep_q == cplrt_small(11) && keep_r == cplrt_small(12));
            CHECK(cx.fault != NULL && cx.fault->kind == CPLRT_FK_DIVISION_BY_ZERO);
            CPLRT(cx_end)(&cx);
            CHECK(CPLRT(cx_begin)(&cx, &rt, &memory, UINT32_MAX, 1, 0, 0, NULL) == CPLRT_OK);
        }
        cplrt_w n = 0;
        CHECK(cplrt_int_neg(&cx, 0, a, &n) == CPLRT_OK);
        cplrt_w back = 0;
        CHECK(cplrt_int_neg(&cx, 0, n, &back) == CPLRT_OK && cplrt_int_cmp(back, a) == 0);
        int eq = 0;
        CHECK(CPLRT(value_equal)(&rt, back, a, &eq) == CPLRT_OK && eq == 1);
        cplrt_release(n);
        cplrt_release(back);
        cplrt_release(a);
        cplrt_release(b);
        cplrt_release(r);
        cplrt_release(q);
    }
}

static void test_division_signs(void)
{
    /* semantics S37: 7 / -2 == -3, 7 % -2 == 1, -7 / 2 == -3, -7 % 2 == -1 */
    static const int64_t cases[][4] = { { 7, 2, 3, 1 },   { 7, -2, -3, 1 },  { -7, 2, -3, -1 }, { -7, -2, 3, -1 },
                                        { 6, 3, 2, 0 },   { -6, 3, -2, 0 },  { 0, -5, 0, 0 },   { 1, 7, 0, 1 },
                                        { -1, 7, 0, -1 }, { 5, 1, 5, 0 },    { 5, -1, -5, 0 } };
    for (size_t i = 0; i < sizeof cases / sizeof cases[0]; i++) {
        cplrt_w q = 0, r = 0;
        CHECK(cplrt_int_divrem(&cx, 0, cplrt_small(cases[i][0]), cplrt_small(cases[i][1]), &q, &r) == CPLRT_OK);
        CHECK(q == cplrt_small(cases[i][2]) && r == cplrt_small(cases[i][3]));
        CHECK(cplrt_fast_div(&cx, 0, cplrt_small(cases[i][0]), cplrt_small(cases[i][1]), &q) == CPLRT_OK);
        CHECK(cplrt_fast_rem(&cx, 0, cplrt_small(cases[i][0]), cplrt_small(cases[i][1]), &r) == CPLRT_OK);
        CHECK(q == cplrt_small(cases[i][2]) && r == cplrt_small(cases[i][3]));
    }
    /* -2^62 / -1 leaves the small range */
    cplrt_w q = 0, r = 0;
    CHECK(cplrt_int_divrem(&cx, 0, cplrt_small(CPLRT_SMALL_MIN), cplrt_small(-1), &q, &r) == CPLRT_OK);
    EXPECT(q, "4611686018427387904");
    CHECK(r == cplrt_small(0) && !cplrt_is_small(q));
    CHECK(cplrt_fast_div(&cx, 0, cplrt_small(CPLRT_SMALL_MIN), cplrt_small(-1), &q) == CPLRT_OK);
    EXPECT(q, "4611686018427387904");
    CHECK(cplrt_fast_rem(&cx, 0, cplrt_small(CPLRT_SMALL_MIN), cplrt_small(-1), &r) == CPLRT_OK);
    CHECK(r == cplrt_small(0));
    cplrt_release(q);
    q = 0;
    /* one output only: -10^23 == 7 * -14285714285714285714285 - 5 */
    cplrt_w only = 0, big = parse("-100000000000000000000000");
    CHECK(cplrt_int_divrem(&cx, 0, big, cplrt_small(7), NULL, &only) == CPLRT_OK);
    EXPECT(only, "-5");
    CHECK(cplrt_int_divrem(&cx, 0, big, cplrt_small(7), &only, NULL) == CPLRT_OK);
    EXPECT(only, "-14285714285714285714285");
    cplrt_release(big);
    cplrt_release(only);
    /* a smaller dividend is its own remainder, shared */
    cplrt_w small_big = parse("4611686018427387904"), larger = parse("-9223372036854775808000");
    CHECK(cplrt_int_divrem(&cx, 0, small_big, larger, &q, &r) == CPLRT_OK);
    CHECK(q == cplrt_small(0) && r == small_big);
    cplrt_release(r);
    cplrt_release(small_big);
    cplrt_release(larger);
}

static void test_small_boundaries(void)
{
    cplrt_w r = 0;
    CHECK(cplrt_int_add(&cx, 0, cplrt_small(CPLRT_SMALL_MAX), cplrt_small(1), &r) == CPLRT_OK);
    EXPECT(r, "4611686018427387904");
    cplrt_w back = 0;
    CHECK(cplrt_int_sub(&cx, 0, r, cplrt_small(1), &back) == CPLRT_OK && back == cplrt_small(CPLRT_SMALL_MAX));
    CHECK(cplrt_int_sub(&cx, 0, cplrt_small(CPLRT_SMALL_MIN), cplrt_small(1), &r) == CPLRT_OK);
    EXPECT(r, "-4611686018427387905");
    CHECK(cplrt_int_neg(&cx, 0, cplrt_small(CPLRT_SMALL_MIN), &r) == CPLRT_OK);
    EXPECT(r, "4611686018427387904");
    CHECK(cplrt_int_neg(&cx, 0, r, &back) == CPLRT_OK && back == cplrt_small(CPLRT_SMALL_MIN));
    CHECK(cplrt_int_neg(&cx, 0, cplrt_small(0), &back) == CPLRT_OK && back == cplrt_small(0));
    CHECK(cplrt_int_mul(&cx, 0, cplrt_small(INT64_C(1) << 31), cplrt_small(INT64_C(1) << 31), &r) == CPLRT_OK);
    CHECK(!cplrt_is_small(r));
    EXPECT(r, "4611686018427387904");
    CHECK(cplrt_int_mul(&cx, 0, cplrt_small(-(INT64_C(1) << 31)), cplrt_small(INT64_C(1) << 31), &r) == CPLRT_OK);
    CHECK(r == cplrt_small(CPLRT_SMALL_MIN));
    CHECK(cplrt_int_mul(&cx, 0, cplrt_small(CPLRT_SMALL_MAX), cplrt_small(0), &r) == CPLRT_OK && r == cplrt_small(0));
    cplrt_w huge = parse("123456789012345678901234567890");
    CHECK(cplrt_int_mul(&cx, 0, huge, cplrt_small(0), &r) == CPLRT_OK && r == cplrt_small(0));
    CHECK(cplrt_int_sub(&cx, 0, huge, huge, &r) == CPLRT_OK && r == cplrt_small(0));
    cplrt_release(huge);
    /* the comparisons with a small constant (cpl_rt.h) */
    cplrt_w neg_big = parse("-4611686018427387905"), pos_big = parse("4611686018427387904");
    CHECK(cplrt_int_lt_small(neg_big, CPLRT_SMALL_MIN) && cplrt_int_gt_small(pos_big, CPLRT_SMALL_MAX));
    CHECK(cplrt_int_le_small(cplrt_small(3), 3) && cplrt_int_ge_small(cplrt_small(3), 3));
    CHECK(cplrt_int_eq_small(cplrt_small(-9), -9) && cplrt_int_ne_small(pos_big, 0));
    CHECK(cplrt_int_cmp(neg_big, pos_big) == -1 && cplrt_int_cmp(pos_big, cplrt_small(0)) == 1);
    CHECK(cplrt_int_cmp(neg_big, cplrt_small(CPLRT_SMALL_MIN)) == -1);
    cplrt_release(neg_big);
    cplrt_release(pos_big);
}

static void test_decimal(void)
{
    static const char *const valid[][2] = {
        { "0", "0" },       { "-0", "0" },       { "+0", "0" },         { "0007", "7" },
        { "+42", "42" },    { "-000123", "-123" }, { "4611686018427387903", "4611686018427387903" },
        { "-4611686018427387904", "-4611686018427387904" }, { "4611686018427387904", "4611686018427387904" },
        { "000000000000000000000000000000000001", "1" },
        { "18446744073709551616", "18446744073709551616" },
        { "-1000000000000000000000000000", "-1000000000000000000000000000" },
        { "100000000000000000000000000000000000001000000000", "100000000000000000000000000000000000001000000000" },
    };
    for (size_t i = 0; i < sizeof valid / sizeof valid[0]; i++) {
        cplrt_w w = parse(valid[i][0]);
        EXPECT(w, valid[i][1]);
        cplrt_w t = 0;
        CHECK(CPLRT(int_text)(&rt, w, &t) == CPLRT_OK && strcmp(cplrt_text_of(t)->utf8, valid[i][1]) == 0);
        CHECK(cplrt_text_of(t)->scalars == strlen(valid[i][1]));
        cplrt_release(t);
        cplrt_release(w);
    }
    static const char *const invalid[] = { "", "+", "-", " 1", "1 ", "1_000", "+-1", "--1", "0x10", "1e3", "1.0",
                                           "\331\241", "12a", "\t7" };
    for (size_t i = 0; i < sizeof invalid / sizeof invalid[0]; i++) {
        cplrt_w keep = cplrt_small(5);
        CHECK(CPLRT(int_parse)(&rt, invalid[i], strlen(invalid[i]), &keep) == CPLRT_INVALID && keep == cplrt_small(5));
    }
    /* a NUL inside the text is not a digit: the length is authoritative */
    cplrt_w keep = cplrt_small(5);
    CHECK(CPLRT(int_parse)(&rt, "1\0002", 3, &keep) == CPLRT_INVALID);
    /* ten thousand digits round-trip */
    size_t n = 10000;
    char *digits = (char *)malloc(n + 2);
    digits[0] = '-';
    for (size_t i = 0; i < n; i++)
        digits[i + 1] = (char)('1' + (int)(i % 9u));
    digits[n + 1] = '\0';
    cplrt_w w = parse(digits);
    EXPECT(w, digits);
    cplrt_w sq = 0, q = 0, r = 0;
    CHECK(cplrt_int_mul(&cx, 0, w, w, &sq) == CPLRT_OK);
    CHECK(cplrt_int_divrem(&cx, 0, sq, w, &q, &r) == CPLRT_OK && cplrt_int_cmp(q, w) == 0 && r == cplrt_small(0));
    cplrt_release(sq);
    cplrt_release(q);
    cplrt_release(w);
    free(digits);
}

static void test_conversions(void)
{
    cplrt_w w = 0;
    int64_t i64 = 0;
    uint64_t u64 = 0;
    CHECK(CPLRT(int_from_u64)(&rt, UINT64_MAX, &w) == CPLRT_OK);
    EXPECT(w, "18446744073709551615");
    CHECK(CPLRT(int_to_u64)(w, &u64) && u64 == UINT64_MAX && !CPLRT(int_to_i64)(w, &i64));
    CHECK(CPLRT(int_from_u64)(&rt, (UINT64_C(1) << 62) - 1u, &w) == CPLRT_OK && cplrt_is_small(w));
    CHECK(CPLRT(int_from_u64)(&rt, UINT64_C(1) << 62, &w) == CPLRT_OK && !cplrt_is_small(w));
    EXPECT(w, "4611686018427387904");
    CHECK(CPLRT(int_from_i64)(&rt, INT64_MIN, &w) == CPLRT_OK);
    EXPECT(w, "-9223372036854775808");
    CHECK(CPLRT(int_to_i64)(w, &i64) && i64 == INT64_MIN && !CPLRT(int_to_u64)(w, &u64));
    CHECK(CPLRT(int_from_i64)(&rt, INT64_MAX, &w) == CPLRT_OK);
    CHECK(CPLRT(int_to_i64)(w, &i64) && i64 == INT64_MAX && CPLRT(int_to_u64)(w, &u64) && u64 == (uint64_t)INT64_MAX);
    CHECK(CPLRT(int_from_i64)(&rt, -5, &w) == CPLRT_OK && w == cplrt_small(-5));
    CHECK(CPLRT(int_to_i64)(w, &i64) && i64 == -5 && !CPLRT(int_to_u64)(w, &u64));
    cplrt_w big = parse("9223372036854775808");
    CHECK(!CPLRT(int_to_i64)(big, &i64) && CPLRT(int_to_u64)(big, &u64) && u64 == (UINT64_C(1) << 63));
    cplrt_release(big);
    big = parse("-9223372036854775809");
    CHECK(!CPLRT(int_to_i64)(big, &i64) && !CPLRT(int_to_u64)(big, &u64));
    cplrt_release(big);
    big = parse("18446744073709551616");
    CHECK(!CPLRT(int_to_u64)(big, &u64));
    /* little-endian arrays of 64-bit words */
    int neg = -1;
    uint64_t words[4] = { 0, 0, 0, 0 };
    CHECK(CPLRT(int_to_words)(big, &neg, NULL, 0) == 2 && neg == 0);
    CHECK(CPLRT(int_to_words)(big, &neg, words, 4) == 2 && words[0] == 0 && words[1] == 1);
    cplrt_release(big);
    const uint64_t in[3] = { 1, 2, 0 };
    CHECK(CPLRT(int_from_words)(&rt, 1, in, 3, &w) == CPLRT_OK);
    EXPECT(w, "-36893488147419103233");
    CHECK(CPLRT(int_to_words)(w, &neg, words, 1) == 2 && neg == 1);
    CHECK(CPLRT(int_to_words)(w, &neg, words, 2) == 2 && words[0] == 1 && words[1] == 2);
    CHECK(CPLRT(int_from_words)(&rt, 1, in, 0, &w) == CPLRT_OK && w == cplrt_small(0)); /* -0 is 0 */
    CHECK(CPLRT(int_to_words)(w, &neg, words, 4) == 0 && neg == 0);
    const uint64_t small_words[1] = { 12345 };
    CHECK(CPLRT(int_from_words)(&rt, 1, small_words, 1, &w) == CPLRT_OK && w == cplrt_small(-12345));
    CHECK(CPLRT(int_to_words)(cplrt_small(-12345), &neg, words, 1) == 1 && neg == 1 && words[0] == 12345);
    const uint64_t top[1] = { UINT64_MAX };
    CHECK(CPLRT(int_from_words)(&rt, 0, top, 1, &w) == CPLRT_OK);
    EXPECT(w, "18446744073709551615");
    cplrt_release(w);
}

static void test_memory(void)
{
    cplrt_runtime small;
    rttest_runtime_init(&small, 1);
    cplrt_cx scx;
    cplrt_memory_record smem;
    CHECK(CPLRT(cx_begin)(&scx, &small, &smem, UINT32_MAX, 1, 0, 0, NULL) == CPLRT_OK);
    cplrt_w r = cplrt_small(9);
    CHECK(cplrt_int_add(&scx, 0, cplrt_small(CPLRT_SMALL_MAX), cplrt_small(1), &r) == CPLRT_FAULT);
    CHECK(r == cplrt_small(9) && scx.fault != NULL && scx.fault->kind == CPLRT_FK_RESOURCE_EXHAUSTION);
    CHECK(scx.fault->resource == CPLRT_RES_MEMORY);
    CPLRT(cx_end)(&scx);
    CHECK(CPLRT(cx_begin)(&scx, &small, &smem, UINT32_MAX, 1, 0, 0, NULL) == CPLRT_OK);
    /* small results need no memory */
    CHECK(cplrt_int_mul(&scx, 0, cplrt_small(1000), cplrt_small(1000), &r) == CPLRT_OK && r == cplrt_small(1000000));
    CHECK(cplrt_int_neg(&scx, 0, cplrt_small(CPLRT_SMALL_MIN), &r) == CPLRT_FAULT && r == cplrt_small(1000000));
    CPLRT(cx_end)(&scx);
    cplrt_w keep = cplrt_small(1);
    CHECK(CPLRT(int_parse)(&small, "99999999999999999999", 20, &keep) == CPLRT_NOMEM && keep == cplrt_small(1));
    cplrt_sbuf b;
    cplrt_sbuf_init(&b, &small);
    CPLRT(int_write)(&b, cplrt_small(5));
    CHECK(b.status == CPLRT_NOMEM);
    CPLRT(sbuf_free)(&b);
    CHECK(rttest_runtime_fini(&small) == 0);
}

int main(void)
{
    rttest_runtime_init(&rt, 0);
    CHECK(CPLRT(cx_begin)(&cx, &rt, &memory, UINT32_MAX, 1, 0, 0, NULL) == CPLRT_OK);
    test_vectors();
    test_division_signs();
    test_small_boundaries();
    test_decimal();
    test_conversions();
    test_memory();
    CPLRT(cx_end)(&cx);
    CHECK(rttest_runtime_fini(&rt) == 0);
    printf("test_int: %d checks, %d failed\n", checks, failures);
    return failures == 0 ? 0 : 1;
}
